def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    chars = list(alphabet)
    index = {c: i for i, c in enumerate(chars)}

    nxt = [[-1] * len(chars)]
    link = [0]
    bad = [False]

    for word in banned:
        state = 0
        for ch in word:
            k = index[ch]
            if nxt[state][k] == -1:
                nxt[state][k] = len(nxt)
                nxt.append([-1] * len(chars))
                link.append(0)
                bad.append(False)
            state = nxt[state][k]
        bad[state] = True

    queue = []
    for k in range(len(chars)):
        child = nxt[0][k]
        if child == -1:
            nxt[0][k] = 0
        else:
            link[child] = 0
            queue.append(child)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        bad[state] = bad[state] or bad[link[state]]

        for k in range(len(chars)):
            child = nxt[state][k]
            if child == -1:
                nxt[state][k] = nxt[link[state]][k]
            else:
                link[child] = nxt[link[state]][k]
                queue.append(child)

    safe_nodes = [i for i in range(len(nxt)) if not bad[i]]
    pos = {state: i for i, state in enumerate(safe_nodes)}
    size = len(safe_nodes)

    mat = [[0] * size for _ in range(size)]
    for i, state in enumerate(safe_nodes):
        for k in range(len(chars)):
            target = nxt[state][k]
            if not bad[target]:
                mat[i][pos[target]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if a[i][k]:
                    aik = a[i][k]
                    for j in range(size):
                        if b[k][j]:
                            result[i][j] = (result[i][j] + aik * b[k][j]) % MOD
        return result

    vector = [0] * size
    vector[pos[0]] = 1

    while n:
        if n & 1:
            new_vector = [0] * size
            for i in range(size):
                if vector[i]:
                    for j in range(size):
                        if mat[i][j]:
                            new_vector[j] = (new_vector[j] + vector[i] * mat[i][j]) % MOD
            vector = new_vector
        mat = multiply(mat, mat)
        n >>= 1

    return sum(vector) % MOD
